 15→// TestBuildTreeWithChanges_EquivalenceWithFlattenRebuild verifies that
 16→// the ApplyTreeChanges-based buildTreeWithChanges produces identical
 17→// tree hashes to the old FlattenTree+BuildTreeFromEntries approach.
 18→func TestBuildTreeWithChanges_EquivalenceWithFlattenRebuild(t *testing.T) { //nolint:paralleltest // t.Chdir requires non-parallel
 19→	repo, dir := setupTestRepo(t)
 20→	store := NewGitStore(repo)
 21→
 22→	// Get the base tree hash from HEAD
 23→	head, err := repo.Head()
 24→	if err != nil {
 25→		t.Fatalf("head: %v", err)
 26→	}
 27→	commit, err := repo.CommitObject(head.Hash())
 28→	if err != nil {
 29→		t.Fatalf("commit: %v", err)
 30→	}
 31→	baseTreeHash := commit.TreeHash
 32→
 33→	// Create modified and deleted files
 34→	modifiedFiles := []string{"file1.txt", "file2.txt"}
 35→	deletedFiles := []string{"file3.txt"}
 36→
 37→	// Write modified files to disk
 38→	for _, f := range modifiedFiles {
 39→		path := filepath.Join(dir, f)
 40→		if err := os.WriteFile(path, []byte("modified content for "+f), 0o600); err != nil {
 41→			t.Fatalf("write %s: %v", f, err)
 42→		}
 43→	}
 44→
 45→	// Create metadata directory with a file
 46→	metadataDir := ".entire/metadata/test-session"
 47→	metadataDirAbs := filepath.Join(dir, metadataDir)
 48→	if err := os.MkdirAll(metadataDirAbs, 0o750); err != nil {
 49→		t.Fatalf("mkdir metadata: %v", err)
 50→	}
 51→	if err := os.WriteFile(filepath.Join(metadataDirAbs, "full.jsonl"), []byte(`{"type":"test"}`), 0o600); err != nil {
 52→		t.Fatalf("write transcript: %v", err)
 53→	}
 54→
 55→	// Switch to repo dir so paths.WorktreeRoot() resolves correctly
 56→	t.Chdir(dir)
 57→
 58→	// --- New approach: ApplyTreeChanges (what buildTreeWithChanges now does) ---
 59→	newHash, err := store.buildTreeWithChanges(baseTreeHash, modifiedFiles, deletedFiles, metadataDir, metadataDirAbs)
 60→	if err != nil {
 61→		t.Fatalf("buildTreeWithChanges (new): %v", err)
 62→	}
 63→
 64→	// --- Old approach: FlattenTree + modify map + BuildTreeFromEntries ---
 65→	oldHash := flattenRebuildTree(t, repo, baseTreeHash, modifiedFiles, deletedFiles, metadataDir, metadataDirAbs, dir)
 66→
 67→	if newHash != oldHash {
 68→		t.Errorf("tree hash mismatch: new=%s old=%s", newHash, oldHash)
 69→	}
 70→}
