230→func flattenRebuildTree(
231→	t *testing.T, repo *gogit.Repository,
232→	baseTreeHash plumbing.Hash,
233→	modifiedFiles, deletedFiles []string,
234→	metadataDir, metadataDirAbs, repoRoot string,
235→) plumbing.Hash {
236→	t.Helper()
237→
238→	baseTree, err := repo.TreeObject(baseTreeHash)
239→	if err != nil {
240→		t.Fatalf("tree: %v", err)
241→	}
242→	entries := make(map[string]object.TreeEntry)
243→	if err := FlattenTree(repo, baseTree, "", entries); err != nil {
244→		t.Fatalf("flatten: %v", err)
245→	}
246→
247→	for _, file := range deletedFiles {
248→		delete(entries, file)
249→	}
250→
251→	for _, file := range modifiedFiles {
252→		absPath := filepath.Join(repoRoot, file)
253→		if !fileExists(absPath) {
254→			delete(entries, file)
255→			continue
256→		}
257→		blobHash, mode, blobErr := createBlobFromFile(repo, absPath)
258→		if blobErr != nil {
259→			continue
260→		}
261→		entries[file] = object.TreeEntry{
262→			Name: file,
263→			Mode: mode,
264→			Hash: blobHash,
265→		}
266→	}
267→
268→	if metadataDir != "" && metadataDirAbs != "" {
269→		if err := addDirectoryToEntriesWithAbsPath(repo, metadataDirAbs, metadataDir, entries); err != nil {
270→			t.Fatalf("add metadata: %v", err)
271→		}
272→	}
273→
274→	hash, err := BuildTreeFromEntries(repo, entries)
275→	if err != nil {
276→		t.Fatalf("build tree: %v", err)
277→	}
278→	return hash
279→}
